-- Restore exactly the pre-Week-8 client profile column grants in the shared project.
-- PostgreSQL table-level REVOKE also removed preexisting column INSERT/UPDATE grants.
-- Do not modify the applied Week 8 migration or grant the protected flag.
begin;
grant insert ("avatar_url","bio","city","created_at","deletion_reason","deletion_requested_at","dm_privacy","external_share_enabled","first_name","followers_count","following_count","hide_stats","id","initials","is_internal","is_private","last_name","last_seen_visible","name","notif_comments","notif_followers","notif_likes","notif_messages","notif_reposts","notifications_enabled","onboarded","presence_epoch","profile_stats","rank_delta","read_receipts","show_wellness","sport","sports","tagline","unit_system","updated_at","username","verified","website") on public.profiles to "anon";
grant update ("avatar_url","bio","city","created_at","deletion_reason","deletion_requested_at","dm_privacy","external_share_enabled","first_name","followers_count","following_count","hide_stats","id","initials","is_internal","is_private","last_name","last_seen_visible","name","notif_comments","notif_followers","notif_likes","notif_messages","notif_reposts","notifications_enabled","onboarded","presence_epoch","profile_stats","rank_delta","read_receipts","show_wellness","sport","sports","tagline","unit_system","updated_at","username","verified","website") on public.profiles to "anon";
