grant insert ("avatar_url","bio","city","dm_privacy","external_share_enabled","first_name","hide_stats","id","initials","is_private","last_name","last_seen_visible","name","notif_comments","notif_followers","notif_likes","notif_messages","notif_reposts","notifications_enabled","onboarded","profile_stats","read_receipts","show_wellness","sport","sports","tagline","unit_system","updated_at","username","website") on public.profiles to "authenticated";
grant update ("avatar_url","bio","city","dm_privacy","external_share_enabled","first_name","hide_stats","initials","is_private","last_name","last_seen_visible","name","notif_comments","notif_followers","notif_likes","notif_messages","notif_reposts","notifications_enabled","onboarded","profile_stats","read_receipts","show_wellness","sport","sports","tagline","unit_system","updated_at","username","website") on public.profiles to "authenticated";
revoke insert (is_superadmin), update (is_superadmin) on public.profiles from "authenticated";
